CREATE DATABASE IF NOT EXISTS eduinsight_ai CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE eduinsight_ai;
SET FOREIGN_KEY_CHECKS=0;
CREATE TABLE IF NOT EXISTS roles (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(40) UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY, role_id INT NOT NULL, name VARCHAR(120) NOT NULL, email VARCHAR(120) UNIQUE NOT NULL, password_hash VARCHAR(255) NOT NULL, active TINYINT DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(role_id) REFERENCES roles(id));
CREATE TABLE IF NOT EXISTS academic_years (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(20) NOT NULL, is_active TINYINT DEFAULT 1);
CREATE TABLE IF NOT EXISTS classes (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(40) NOT NULL, grade VARCHAR(20), homeroom_teacher VARCHAR(120), academic_year_id INT NULL, FOREIGN KEY(academic_year_id) REFERENCES academic_years(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS subjects (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL, code VARCHAR(20) UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS students (id INT AUTO_INCREMENT PRIMARY KEY, nis VARCHAR(30) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL, gender ENUM('L','P') NOT NULL, class_id INT NULL, class_name VARCHAR(30) DEFAULT NULL, attendance_rate DECIMAL(5,2) DEFAULT 0, birth_date DATE NULL, address TEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(class_id) REFERENCES classes(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS assessments (id INT AUTO_INCREMENT PRIMARY KEY, student_id INT NOT NULL, subject_id INT NULL, subject VARCHAR(80) NOT NULL, knowledge_score DECIMAL(5,2) NOT NULL, skill_score DECIMAL(5,2) NOT NULL, assignment_rate DECIMAL(5,2) DEFAULT 0, assessment_date DATE NOT NULL, notes TEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE, FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS learning_materials (id INT AUTO_INCREMENT PRIMARY KEY, subject_id INT NULL, title VARCHAR(160) NOT NULL, description TEXT, level ENUM('Dasar','Menengah','Lanjutan') DEFAULT 'Dasar', resource_url VARCHAR(255), FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS recommendations (id INT AUTO_INCREMENT PRIMARY KEY, student_id INT NOT NULL, assessment_id INT NULL, action_label VARCHAR(40) NOT NULL, material_id INT NULL, confidence DECIMAL(5,2) NOT NULL, explanation TEXT NOT NULL, teacher_decision TEXT NULL, status ENUM('Baru','Ditinjau','Selesai') DEFAULT 'Baru', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE, FOREIGN KEY(assessment_id) REFERENCES assessments(id) ON DELETE SET NULL, FOREIGN KEY(material_id) REFERENCES learning_materials(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS student_progress (id INT AUTO_INCREMENT PRIMARY KEY, student_id INT NOT NULL, period_name VARCHAR(40) NOT NULL, average_score DECIMAL(5,2) NOT NULL, attendance_rate DECIMAL(5,2) DEFAULT 0, teacher_note TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE);
SET FOREIGN_KEY_CHECKS=1;
